#!/usr/bin/env node
/*
 * make_requirements.js — R1 (registration §4.4): what each measure needs from the data, taken from the measure
 * itself, as the basis of the readiness checks. Open content only (CMS's measure bundles); no data.
 *
 *   node pipeline/readiness/checks/make_requirements.js > pipeline/readiness/checks/measure_requirements.json
 *
 * Two parts:
 *   data_requirements   generated by CMS's engine (fqm-execution Calculator.calculateDataRequirements) from
 *                       each bundle: resource type, QI-Core profile, value-set code filter, status filter
 *   value_sets          every value set the measure's logic declares, and whether the bundle carries its
 *                       expansion (a missing expansion is a measure-package problem: the engine cannot
 *                       evaluate without it)
 *   element_rules       elements the logic reads beyond the code filter (units of compared values, timing,
 *                       references, status values the data requirements do not list), each with the CQL
 *                       expression that uses it, from reading the measures' CQL (same bundles)
 * The SQL checks (pipeline/readiness/sql/55_r1_checks.sql) implement these per record.
 */
const fs = require('fs');
const path = require('path');
const { createRequire } = require('module');

const ROOT = path.join(__dirname, '..', '..', '..');
const fqm = createRequire(path.join(ROOT, 'testcases/package.json'))('fqm-execution');
const MEASURES = ['CMS816FHIRHHHypo', 'CMS871FHIRHHHyper'];

const ELEMENT_RULES = [
  { role: 'glucose_result', resource: 'Observation', element: 'valueQuantity (UCUM, mass per volume)',
    rule: 'value compared with mg/dL thresholds (40, 80, 200, 300, 600); CMS FHIRHelpers.ToQuantity accepts UCUM units only',
    used_by: ['CMS816: Glucose Test With Result Less Than 40, Low Glucose Test Followed By Glucose Test Result Greater Than 80',
      'CMS871: Encounter with Elevated Glucose Greater Than or Equal to 200, Days with Hyperglycemic Events, Glucose Greater Than 600 ...'] },
  { role: 'glucose_result', resource: 'Observation', element: 'effective[x]',
    rule: 'result time placed in the hospitalization / in a day / within 24 h of a dose',
    used_by: ['CMS816: Glucose Test With Result Less Than 40', 'CMS871: Days with Glucose Results'] },
  { role: 'glucose_result', resource: 'Observation', element: 'status in final | amended | corrected',
    rule: 'data requirement status filter', used_by: ['both measures'] },
  { role: 'medication_cms816', resource: 'MedicationAdministration', element: 'status = completed',
    rule: 'only completed administrations count', used_by: ['CMS816: Hypoglycemic Medication Administration'] },
  { role: 'medication_cms871', resource: 'MedicationAdministration', element: 'status in completed | in-progress',
    rule: 'data requirement status filter', used_by: ['CMS871: Encounter with Hypoglycemic Medication'] },
  { role: 'medication_cms816', resource: 'MedicationAdministration', element: 'effective[x] start',
    rule: 'dose start within the hospitalization and within 24 h before a low result',
    used_by: ['CMS816: Hypoglycemic Medication Administration, Severe Hypoglycemic Harm Event'] },
  { role: 'medication_cms871', resource: 'MedicationAdministration', element: 'effective[x] with an end',
    rule: 'the whole administration period must lie in the hospitalization; a period without an end never does',
    used_by: ['CMS871: Encounter with Hypoglycemic Medication'] },
  { role: 'medication_cms816', resource: 'MedicationAdministration', element: 'RxNorm code at the term types the value set lists',
    rule: 'value-set membership is exact on code; a brand or ingredient code of the same drug does not match', used_by: ['both measures'] },
  { role: 'medication_cms816', resource: 'MedicationAdministration', element: 'status consistent with the recorded eMAR event',
    rule: 'a not-given dose recorded as completed counts as a dose (MIMIC-specific: the event is kept in dosage.method)',
    used_by: ['CMS816: Hypoglycemic Medication Administration', 'CMS871: Encounter with Hypoglycemic Medication'] },
  { role: 'encounter', resource: 'Encounter', element: 'status = finished; period start and end',
    rule: 'inpatient encounter ending in the measurement period', used_by: ['CQMCommon: Inpatient Encounter; both measures: Qualifying Encounter'] },
  { role: 'encounter', resource: 'Encounter', element: 'reasonReference / diagnosis to its diagnoses',
    rule: 'encounter diagnoses are reached through the encounter', used_by: ['CMS871: Encounter with Existing Diabetes Diagnosis'] },
  { role: 'diabetes_diagnosis', resource: 'Condition', element: 'onset and clinicalStatus (or abatement)',
    rule: 'QICoreCommon prevalenceInterval() is null for a condition that is neither active nor abated',
    used_by: ['CMS871: Encounter with Existing Diabetes Diagnosis'] },
  { role: 'all', resource: 'all retrieved types', element: 'subject reference to the Patient',
    rule: 'patient-level retrieval', used_by: ['all retrieves'] },
  { role: 'all', resource: 'all retrieved types', element: 'meta.profile = the QI-Core profile of the retrieve',
    rule: 'the engine retrieves by profile (trustMetaProfile default true): an undeclared profile is invisible', used_by: ['all retrieves'] },
];

(async () => {
  const out = { generated_utc: new Date().toISOString(), engine: 'fqm-execution ' + require(createRequire(path.join(ROOT, 'testcases/package.json')).resolve('fqm-execution/package.json')).version,
    measures: {}, element_rules: ELEMENT_RULES };
  const quiet = console.log; const warn = console.warn;
  for (const m of MEASURES) {
    const p = path.join(ROOT, `vendor/dqm-content/bundles/measure/${m}/${m}-bundle.json`);
    const b = JSON.parse(fs.readFileSync(p));
    console.log = () => {}; console.warn = () => {};
    const r = await fqm.Calculator.calculateDataRequirements(b);
    console.log = quiet; console.warn = warn;
    const present = new Set(b.entry.filter(e => e.resource.resourceType === 'ValueSet').map(e => e.resource.url));
    const declared = new Set();
    for (const { resource: lib } of b.entry) if (lib.resourceType === 'Library') for (const c of lib.content || [])
      if (c.contentType === 'text/cql' && c.data) for (const x of Buffer.from(c.data, 'base64').toString('utf8')
        .matchAll(/valueset "([^"]+)": '(http:\/\/cts\.nlm\.nih\.gov\/fhir\/ValueSet\/[0-9.]+)'/g)) declared.add(JSON.stringify([x[1], x[2]]));
    out.measures[m] = {
      bundle: path.relative(ROOT, p),
      data_requirements: (r.results.dataRequirement || []).map(d => ({
        type: d.type, profile: (d.profile || [])[0] || null,
        code_filters: (d.codeFilter || []).map(c => ({ path: c.path, value_set: c.valueSet || null, codes: (c.code || []).map(x => x.code) })),
        date_filters: (d.dateFilter || []).map(x => x.path) })),
      value_sets: [...declared].map(s => JSON.parse(s)).map(([name, url]) => ({ name, oid: url.split('/').pop(), expansion_in_bundle: present.has(url) }))
        .sort((x, y) => x.oid.localeCompare(y.oid)),
    };
  }
  process.stdout.write(JSON.stringify(out, null, 2) + '\n');
})();
